import assert from 'node:assert/strict';
import {test} from 'node:test';
import {canonicalJson,contentHash} from '../../../contracts/canonical.ts';
const m=await import(new URL('../../../apps/server/modules/documents/source-content-request-record.ts',import.meta.url).href).catch(e=>{if(e.code==='ERR_MODULE_NOT_FOUND')return {};throw e;});
const lineageServerModule=await import('../../../apps/server/modules/documents/source-content-server-context.ts');
const id=(n:number)=>`70000000-0000-4000-8000-${String(n).padStart(12,'0')}`,ref=(n:number)=>({id:id(n),version:1,contentHash:'a'.repeat(64)});
const zero=Date.parse('2026-10-23T10:00:00.000Z'),at=(ms:number)=>new Date(zero+ms).toISOString();
function serverPreparedWire(){const v:any=lineageServerModule;assert.equal(typeof v.readSourceContentPreparedVerificationWireFromServerContextCandidate,'function','서버 준비 프레임 wire 소비 미구현');return v.readSourceContentPreparedVerificationWireFromServerContextCandidate;}
function heldPreparedWire(){const v:any=lineageServerModule;assert.equal(typeof v.readSourceContentPreparedVerificationWireFromHeldIdentityCandidate,'function','보유 문맥 준비 프레임 wire 소비 미구현');return v.readSourceContentPreparedVerificationWireFromHeldIdentityCandidate;}
test('관리 원문은 준비선행 서버소비에 연결하고 문맥 전 expected/basis를 고정한다',async()=>{
 const f=preparedManagedFixture(),s=preparationSources({row:f.r}),raw=JSON.stringify(f.bundle.evidence),basis=proofBasis(f.r),wanted=structuredClone(basis.requestRef);let calls=0;const out=await serverPreparedWire()({async query(){return {rows:[f.sequence[calls++]]};}},{...s,async readIdentityCandidate(){basis.requestRef.contentHash='f'.repeat(64);f.bundle.expected.actorId=id(99);return s.readIdentityCandidate();}},basis,raw,f.bundle.expected,'requestSourceContentHash',0,zero+5000);
 assert.equal(calls,6);assert.equal(out.reason,'CURRENT_VERIFIER_UNAVAILABLE');assert.deepEqual(out.requestRef,wanted);assert.ok(out.policyLineage);assert.ok(out.lineage);assert.equal(out.readConsistency,'SEPARATE_READS_NOT_ATOMIC');for(const k of ['storedRequestAuthenticated','managementEvidenceVerified','signatureVerified','bodyBytesVerified','verifierEvidenceVerified','preparationAuthorized','currentAuthorityVerified','storageMutationPerformed','executionAuthorized','linkAuthorized'] as const)assert.equal(out[k],false);assert.equal(JSON.stringify(out).includes('합성 원문서'),false);
});
test('원문 중복/escaped중복·유효JSON 크기초과·형식오류는 문맥조회 전에 닫힌다',async()=>{
 const f=preparedManagedFixture(),raw=JSON.stringify(f.bundle.evidence),duplicate='{"previousEvent":null,'+raw.slice(1),escaped='{"previous\\u0045vent":null,'+raw.slice(1),oversized=raw+' '.repeat(4194305);for(const value of [duplicate,escaped,oversized])assert.deepEqual(JSON.parse(value),JSON.parse(raw));let identities=0,calls=0;const s=preparationSources({row:f.r}),sources={...s,async readIdentityCandidate(){identities++;return s.readIdentityCandidate();}},db={async query(){calls++;return {rows:[]};}};
 for(const value of [duplicate,escaped,oversized,'{',null,{}])await assert.rejects(serverPreparedWire()(db,sources,proofBasis(f.r),value,f.bundle.expected,'requestSourceContentHash',0,zero+5000),/^Error: SOURCE_CONTENT_SERVER_MANAGEMENT_WIRE_INVALID$/);assert.equal(identities,0);assert.equal(calls,0);
 let gets=0;const expected={...f.bundle.expected};Object.defineProperty(expected,'actorId',{enumerable:true,get(){gets++;return id(7);}});await assert.rejects(serverPreparedWire()(db,sources,proofBasis(f.r),raw,expected,'requestSourceContentHash',0,zero+5000),/SOURCE_CONTENT_SERVER_MANAGEMENT_INPUT_INVALID/);assert.equal(gets,0);assert.equal(identities,0);
});
test('준비 wire 소비도 문서격리와 원오류·held만료0/회수1 경계를 보존한다',async()=>{
 const f=preparedManagedFixture(),s=preparationSources({row:f.r}),raw=JSON.stringify(f.bundle.evidence);f.document.artifact_state='QUARANTINED';let calls=0;const out=await serverPreparedWire()({async query(){return {rows:[f.sequence[calls++]]};}},s,proofBasis(f.r),raw,f.bundle.expected,'requestSourceContentHash',0,zero+5000);assert.equal(calls,5);assert.equal(out.reason,'ARTIFACT_QUARANTINED');assert.equal(out.lineage,null);assert.equal(out.preparationAuthorized,false);
 calls=0;const error=Error('SYNTHETIC_PREPARED_WIRE_QUERY');await assert.rejects(serverPreparedWire()({async query(){calls++;if(calls===3)throw error;return {rows:[f.sequence[calls-1]]};}},s,proofBasis(f.r),raw,f.bundle.expected,'requestSourceContentHash',0,zero+5000),e=>e===error);assert.equal(calls,3);
 const h=heldFixture();calls=0;const db={async query(){calls++;return {rows:[h.control]};}};const expired=await heldPreparedWire()(db,h.held,proofBasis(f.r),raw,f.bundle.expected,'requestSourceContentHash',0,zero+60000);assert.equal(calls,0);assert.equal(expired.reason,'SERVER_IDENTITY_CANDIDATE_INVALID');h.control.control_revoked_at=at(1000);const revoked=await heldPreparedWire()(db,h.held,proofBasis(f.r),raw,f.bundle.expected,'requestSourceContentHash',0,zero+5000);assert.equal(calls,1);assert.equal(revoked.reason,'PROJECT_CONTROL_UNAVAILABLE');
});
function serverPreparedVerification(){const v:any=lineageServerModule;assert.equal(typeof v.readSourceContentPreparedVerificationFromServerContextCandidate,'function','서버 준비 프레임 선행 소비 미구현');return v.readSourceContentPreparedVerificationFromServerContextCandidate;}
function heldPreparedVerification(){const v:any=lineageServerModule;assert.equal(typeof v.readSourceContentPreparedVerificationFromHeldIdentityCandidate,'function','보유 문맥 준비 프레임 선행 소비 미구현');return v.readSourceContentPreparedVerificationFromHeldIdentityCandidate;}
test('서버 준비 프레임 연결은 문맥 전 입력고정·원scope의 순차6조회·권위false를 유지한다',async()=>{
 const f=preparedManagedFixture(),s=preparationSources({row:f.r}),basis=proofBasis(f.r),wanted=structuredClone(basis.requestRef),order:string[]=[];let calls=0;const db={async query(){calls++;order.push(['record','policy','root','registration','document','verification'][calls-1]!);return {rows:[f.sequence[calls-1]]};}};
 const out=await serverPreparedVerification()(db,{async readIdentityCandidate(d:unknown){assert.equal(d,db);order.push('identity');basis.requestRef.contentHash='f'.repeat(64);f.bundle.expected.actorId=id(99);return s.readIdentityCandidate();},async readControlCandidate(d:unknown){assert.equal(d,db);order.push('control');return s.readControlCandidate();}},basis,f.bundle,'requestSourceContentHash',0,zero+5000);
 assert.deepEqual(order,['identity','control','record','policy','root','registration','document','verification']);assert.equal(calls,6);assert.equal(out.reason,'CURRENT_VERIFIER_UNAVAILABLE');assert.deepEqual(out.requestRef,wanted);assert.equal(out.readConsistency,'SEPARATE_READS_NOT_ATOMIC');for(const k of ['storedRequestAuthenticated','managementEvidenceVerified','signatureVerified','bodyBytesVerified','verifierEvidenceVerified','preparationAuthorized','currentAuthorityVerified','storageMutationPerformed','executionAuthorized','linkAuthorized'] as const)assert.equal(out[k],false);assert.equal(JSON.stringify(out).includes('합성 원문서'),false);
});
test('서버 위치/등록/문서 음성은 검증계보 조회 전에 닫힌다',async()=>{
 for(const kind of ['ROOT','REGISTRATION','DOCUMENT']){const f=preparedManagedFixture();if(kind==='ROOT'){f.root.status='REVOKED';f.root.content_hash=contentHash(canonicalJson({declaration:f.root.declaration_json,status:'REVOKED',authority:f.root.authority,readiness:f.root.readiness,reason:f.root.reason}));}if(kind==='REGISTRATION'){f.registration.registration_state='REVOKED';f.registration.registration_revoked_at=at(1000);}if(kind==='DOCUMENT')f.document.artifact_state='QUARANTINED';let calls=0;const out=await serverPreparedVerification()({async query(){return {rows:[f.sequence[calls++]]};}},preparationSources({row:f.r}),proofBasis(f.r),f.bundle,'requestSourceContentHash',0,zero+5000);assert.equal(calls,kind==='ROOT'?3:kind==='REGISTRATION'?4:5);assert.equal(out.reason,kind==='ROOT'?'SOURCE_ROOT_REVOKED':kind==='REGISTRATION'?'REGISTRATION_NOT_AVAILABLE':'ARTIFACT_QUARANTINED');assert.equal(out.verificationRef,null);assert.equal(out.lineage,null);assert.equal(out.preparationAuthorized,false);}
});
test('서버 준비 연결은 입력선검사/문맥부재·held만료0/회수1과 후속query 원오류를 보존한다',async()=>{
 const f=preparedManagedFixture(),s=preparationSources({row:f.r});let calls=0,gets=0,identities=0;const db={async query(){calls++;return {rows:[]};}},sources={...s,async readIdentityCandidate(){identities++;return s.readIdentityCandidate();}},g={...f.bundle};Object.defineProperty(g,'expected',{enumerable:true,get(){gets++;return f.bundle.expected;}});
 await assert.rejects(serverPreparedVerification()(db,sources,proofBasis(f.r),g,'requestSourceContentHash',0,zero+5000),/SOURCE_CONTENT_SERVER_MANAGEMENT_INPUT_INVALID/);await assert.rejects(serverPreparedVerification()(db,sources,proofBasis(f.r),f.bundle,'requestSourceContentHash',200,zero+5000),/SOURCE_CONTENT_SERVER_VERIFICATION_INPUT_INVALID/);await assert.rejects(serverPreparedVerification()(db,sources,proofBasis(f.r),f.bundle,'unknown',0,zero+5000),/SOURCE_CONTENT_SERVER_MANAGEMENT_INPUT_INVALID/);assert.equal(calls,0);assert.equal(gets,0);assert.equal(identities,0);
 const absent=await serverPreparedVerification()(db,{},proofBasis(f.r),f.bundle,'requestSourceContentHash',0,zero+5000);assert.equal(absent.reason,'SERVER_CONTEXT_READERS_UNAVAILABLE');assert.equal(absent.policyLineage,null);assert.equal(absent.lineage,null);assert.equal(absent.preparationAuthorized,false);
 const h=heldFixture();const expired=await heldPreparedVerification()(db,h.held,proofBasis(f.r),f.bundle,'requestSourceContentHash',0,zero+60000);assert.equal(calls,0);assert.equal(expired.reason,'SERVER_IDENTITY_CANDIDATE_INVALID');h.control.control_revoked_at=at(1000);const revoked=await heldPreparedVerification()({async query(){calls++;return {rows:[h.control]};}},h.held,proofBasis(f.r),f.bundle,'requestSourceContentHash',0,zero+5000);assert.equal(calls,1);assert.equal(revoked.reason,'PROJECT_CONTROL_UNAVAILABLE');
 for(const failAt of [3,4,5,6]){calls=0;const error=Error('SYNTHETIC_SERVER_PREPARED_QUERY');await assert.rejects(serverPreparedVerification()({async query(){calls++;if(calls===failAt)throw error;return {rows:[f.sequence[calls-1]]};}},s,proofBasis(f.r),f.bundle,'requestSourceContentHash',0,zero+5000),e=>e===error);assert.equal(calls,failAt);}
});
function preparedManaged(){assert.equal(typeof m.readSourceContentStoredPreparedVerificationForDeclaredContextCandidate,'function','원저장 위치·등록·문서 선행 결합 미구현');return m.readSourceContentStoredPreparedVerificationForDeclaredContextCandidate;}
function preparedManagedFixture(){
 const f=managedVerificationFixture(),p=readyStored(),r=f.r,s=r.scope_json,e=f.bundle.evidence,x=f.bundle.expected;
 for(const key of ['sourceRootRef','connectorRef','registrationRef','targets'] as const)s[key]=structuredClone(p.row.scope_json[key]);
 for(const key of ['sourceRootRef','connectorRef','registrationRef','targets'] as const){e.originalRequest.payload.definition[key]=s[key];e.policyEvent.snapshot_json[key]=s[key];}
 e.policyEvent.content_hash=contentHash(canonicalJson(e.policyEvent.snapshot_json));const policyRef={id:e.policyEvent.id,version:1,contentHash:e.policyEvent.content_hash};x.policyRef=policyRef;s.contentPolicyRef=policyRef;Object.assign(e.command.resultRef.data,{ref:policyRef,policyRef});e.command.requestHash=contentHash(canonicalJson(e.originalRequest));
 const managementDigest=contentHash(canonicalJson({projectId:x.projectId,actorId:x.actorId,clientId:x.clientId,controlGeneration:x.controlGeneration,requestHash:e.command.requestHash,policyRef:x.basePolicyRef,targetRef:policyRef}));e.receipt.scopeDigest=managementDigest;Object.assign(e.audit,{scopeDigest:managementDigest,targetRef:policyRef});
 const payload=Object.fromEntries(['sourceRootRef','connectorRef','registrationRef','observerRef','targets','limits','expiresAt','reason'].map(k=>[k,s[k]]));r.created_command.requestHash=contentHash(canonicalJson({schemaVersion:1,projectId:s.projectId,commandId:r.created_command.commandId,clientId:s.clientId,controlGeneration:s.controlGeneration,operation:'requestSourceContentHash',targetId:null,expectedVersion:0,baselineRefs:[],approvalRef:null,payload}));
 r.scope_digest=contentHash(canonicalJson(s));const requestRef={id:r.id,version:1,contentHash:r.scope_digest};Object.assign(r.created_command.resultRef.data,{ref:requestRef,requestRef,scopeDigest:r.scope_digest,scope:s});const creationDigest=contentHash(canonicalJson({projectId:s.projectId,actorId:s.userId,clientId:s.clientId,controlGeneration:s.controlGeneration,requestHash:r.created_command.requestHash,policyRef:s.basePolicyRef,targetRef:requestRef}));r.authorization_receipt.scopeDigest=creationDigest;Object.assign(r.creation_audits[0],{scopeDigest:creationDigest,targetRef:requestRef});
 for(const value of [r.preflight_json,r.challenge_json])Object.assign(value,{requestRef,scopeDigest:r.scope_digest,connectorRef:s.connectorRef,registrationRef:s.registrationRef});r.preflight_digest=contentHash(canonicalJson(r.preflight_json));Object.assign(r.permit_json,{scope:s,requestRef,scopeDigest:r.scope_digest});r.permit_json.root.sourceRootRef=s.sourceRootRef;
 const report=r.observation.report;Object.assign(report,{requestRef,scopeDigest:r.scope_digest,connectorRef:s.connectorRef,registrationRef:s.registrationRef});report.root.facts.declaredRootRef=s.sourceRootRef;report.files[0].documentRef=s.targets[0].documentRef;const {signature,reportHash,...unsigned}=report;report.reportHash=contentHash(canonicalJson(unsigned));r.observation.contentHash=report.reportHash;r.observation.scopeDigest=r.scope_digest;Object.assign(r.report_audits[0],{scopeDigest:r.scope_digest,targetRef:{id:r.observation.id,version:1,contentHash:report.reportHash}});f.verification.observation_hash=report.reportHash;f.verification.document_hash=s.targets[0].documentRef.contentHash;
 return {...f,root:p.root,registration:p.registration,document:p.document,sequence:[r,{current:structuredClone(e.policyEvent),previous:null},p.root,p.registration,p.document,{current:f.verification,previous:null}]};
}
